Definition LITS : list (Z * Z) := [(0x13f7f, 0x140bf); (0x14b3c, 0x14c7c); (0x17e7c, 0x17f7c); (0x20dfd, 0x20f3d)].   (* [comment removed for export] *)
Definition inr (L : list (Z * Z)) (a : Z) : Prop := Exists (fun r => fst r <= a < snd r) L.
Definition litsh (m : word -> option byte) : Prop := forall a, inr LITS a -> m (Z_to_bv 64 (a / 8 + SB)) = Some (Z_to_bv 8 0).
Definition zwin (m : word -> option byte) (lo hi : Z) : Prop := forall a, lo <= a < hi -> m (Z_to_bv 64 (a / 8 + SB)) = Some (Z_to_bv 8 0).
Definition env (m : word -> option byte) (lo hi : Z) : Prop :=
  WLO <= lo /\ hi <= 2 ^ 47 /\ lo mod 8 = 0 /\ zwin m lo hi /\ L5.img_clear m 0x10000 0x158000 /\ cells m /\ fmtsh m /\ litsh m.
(* [comment removed for export] *)
Definition wok (W : list ivl) : Prop := Forall (fun iv => IMGTOP <= fst iv /\ (snd iv <= BIGSHADOW_LO \/ WLO <= fst iv)) W.

Lemma outside_of_wok W x : wok W -> (x < IMGTOP \/ BIGSHADOW_LO <= x < WLO) -> outside W x.
Proof.
