Lemma memset_icpt_call : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (lo hi n : Z),
  env m lo hi -> stk rsegs m lo (bv_unsigned sp) ->
  lo + 2216 <= bv_unsigned sp -> bv_unsigned sp <= bv_unsigned a0 -> bv_unsigned a0 + n + 64 <= hi -> 0 < n <= 2 ^ 40 ->
  store_ok rsegs m a0 (Z.to_nat n) = true -> a2 = Z_to_bv 64 n -> bv_unsigned ra mod 2 = 0 -> mem_inv rsegs m ->
  evt rsegs (fun ms' => exists m1 t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6',
      ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 a0 a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F ra fc None (write_to_mem m1 a0 (repeat (Z_to_bv 8 (bv_unsigned a1)) (Z.to_nat n))) (seg_rom rsegs)
      /\ munch [(bv_unsigned sp - 2216, bv_unsigned sp)] m m1 /\ mem_grows m m1 /\ mem_inv rsegs m1 /\ store_ok rsegs m1 a0 (Z.to_nat n) = true)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0x7ebb0) fc None m (seg_rom rsegs)).
Proof.
