(* [comment removed for export] *)
Definition zhull (m : word -> option byte) (p n : Z) : Prop :=
  forall x : Z, SB + p / 8 - 7 <= x -> x <= SB + (p + n - 1) / 8 + 7 -> m (Z_to_bv 64 x) = Some (Z_to_bv 8 0).
Lemma zhull_win m lo hi p n : zwin m lo hi -> lo mod 8 = 0 -> 0 <= lo -> hi <= 2 ^ 47 -> lo + 64 <= p -> p + n + 64 <= hi -> 0 < n -> zhull m p n.
