Definition WIN : Z := 10448.
Definition senv (m : word -> option byte) (lo : Z) : Prop := env m lo (lo + WIN).
(* [comment removed for export] *)
Definition srcok (lo p n : Z) : Prop :=
  (lo + 64 <= p /\ p + n + 64 <= lo + WIN) \/ (0x13fbf + 64 <= p /\ p + n + 64 <= 0x140bf) \/ (0x14b3c + 64 <= p /\ p + n + 64 <= 0x14c7c)
  \/ (0x17e7c + 64 <= p /\ p + n + 64 <= 0x17f7c) \/ (0x20dfd + 64 <= p /\ p + n + 64 <= 0x20f3d).
