(* [comment removed for export] *)
Definition tush (m : word -> option byte) (pd : Z) : Prop :=
  pd mod 64 = 32 /\ IMGTOP <= pd /\ pd + 160 <= 2 ^ 47 /\ (pd + 100 <= BIGSHADOW_LO \/ WLO <= pd)     (* [comment removed for export] *)
  /\ (exists w, rdn rsegs m (Z_to_bv 64 (pd / 8 + SB - 4)) 8 = Some w)
  /\ (forall i, 0 <= i < 4 -> m (Z_to_bv 64 (pd / 8 + SB + i)) = Some (Z_to_bv 8 0)).
Lemma tush_munch W m m' pd : tush m pd -> munch W m m' -> wok W -> tush m' pd.
Proof.
