Ltac transport_after_call segs m m' MU WM ::=
  let W := lazymatch type of MU with munch ?W _ _ => W end in
  repeat match goal with
  | H : bytes_at segs m ?A2 ?bs2 |- _ =>
      first [ apply (bytes_at_transport segs W m m' A2 bs2) in H; [ | exact MU | cbn [disjoint_from]; simpl_sizes; slia ]
            | idtac "note: dropping hypothesis (not provably disjoint from callee footprint):" H; clear H ]
  | H : wr_at segs m ?A2 ?n2 |- _ => apply (wr_at_transport segs m m' A2 n2) in H; [ | exact WM ]
  | H : rw_cells segs m ?A2 ?cs2 |- _ =>
      first [ apply (rw_cells_transport segs W m m' A2 cs2) in H; [ | exact MU | exact WM | cbn [disjoint_from]; simpl_sizes; slia ]
            | idtac "note: dropping hypothesis (not provably disjoint from callee footprint):" H; clear H ]
  | H : ro_cells segs m ?A2 ?cs2 |- _ =>
      first [ apply (ro_cells_transport segs W m m' A2 cs2) in H; [ | exact MU | cbn [disjoint_from]; simpl_sizes; slia ]
            | idtac "note: dropping hypothesis (not provably disjoint from callee footprint):" H; clear H ]
  | H : u8arr segs m ?A2 ?xs |- _ =>
      first [ apply (u8arr_transport segs W m m' A2 xs) in H; [ | exact MU | exact WM | cbn [disjoint_from]; simpl_sizes; simpl_arr_sizes; slia ]
            | idtac "note: dropping hypothesis (not provably disjoint from callee footprint):" H; clear H ]
  | H : u32arr segs m ?A2 ?xs |- _ =>
      first [ apply (u32arr_transport segs W m m' A2 xs) in H; [ | exact MU | exact WM | cbn [disjoint_from]; simpl_sizes; simpl_arr_sizes; slia ]
            | idtac "note: dropping hypothesis (not provably disjoint from callee footprint):" H; clear H ]
  | H : u64arr segs m ?A2 ?xs |- _ =>
      first [ apply (u64arr_transport segs W m m' A2 xs) in H; [ | exact MU | exact WM | cbn [disjoint_from]; simpl_sizes; simpl_arr_sizes; slia ]
            | idtac "note: dropping hypothesis (not provably disjoint from callee footprint):" H; clear H ]
  | H : u8ro segs m ?A2 ?xs |- _ =>
      first [ apply (u8ro_transport segs W m m' A2 xs) in H; [ | exact MU | cbn [disjoint_from]; simpl_sizes; simpl_arr_sizes; slia ]
            | idtac "note: dropping hypothesis (not provably disjoint from callee footprint):" H; clear H ]
  | H : stk segs m ?loq ?hiq |- _ =>
      first [ apply (stk_transport_disjoint segs W m m' loq hiq) in H; [ | exact MU | exact WM | cbn [disjoint_from]; slia ]
            | clear H ]
  | H : munch ?Wq ?mq m |- _ =>
      first [ apply (munch_trans Wq mq m m') in H; [ | eapply (munch_weaken W Wq m m'); [ unfold sub_fp; cbn [outside]; intros; slia | exact MU ] ]
            | fail 100 "callee footprint not inside caller footprint" ]
  | H : wmono segs ?mq m |- _ => apply (wmono_trans segs mq m m') in H; [ | exact WM ]
  | H : WAI.senv m ?loq |- _ =>
      first [ let G := fresh "WL" in pose proof (proj1 H : WAI.WLO <= loq) as G; unfold WAI.WLO in G;
              apply (fun E => WAI.senv_munch W m m' loq E MU) in H;
              [ clear G | unfold WAI.wok; repeat (apply Forall_cons; [cbn [fst snd]; unfold WAI.IMGTOP, BIGSHADOW_LO, WAI.WLO; slia |]); apply Forall_nil ]
            | idtac "note: dropping the interceptor environment (callee footprint not provably apart from it):" H; clear H ]
  | H : WAI.tush m ?pdq |- _ =>
      first [ apply (fun T => WAI.tush_munch W m m' pdq T MU) in H;
              [ | unfold WAI.wok; repeat (apply Forall_cons; [cbn [fst snd]; unfold WAI.IMGTOP, BIGSHADOW_LO, WAI.WLO; slia |]); apply Forall_nil ]
            | idtac "note: dropping the TU-buffer shadow facts (callee footprint not provably apart from them):" H; clear H ]
  end.

Ltac footprint_after_store segs m a bs ::=
  repeat match goal with
  | MU : munch ?Wq ?mq m |- _ =>
      first [ apply (munch_write Wq mq m a bs) in MU; [ | lia | simpl_sizes; slia | cbn [inside]; simpl_sizes; slia ]
            | fail 100 "store outside the declared footprint:" a ]
  | WMo : wmono segs ?mq m |- _ => apply (wmono_write segs mq m (wa a) bs) in WMo
  | STq : stk segs m ?loq ?hiq |- _ =>
      first [ apply (stk_write segs m loq hiq a bs) in STq; [ | lia | simpl_sizes; slia ]
            | fail 100 "cannot transport stk hypothesis" STq ]
  | H : WAI.senv m ?loq |- _ =>
      first [ let G := fresh "WL" in pose proof (proj1 H : WAI.WLO <= loq) as G; unfold WAI.WLO in G;
              apply (WAI.senv_write m loq a bs) in H;
              [ clear G | unfold WAI.IMGTOP; simpl_sizes; slia | simpl_sizes; slia | unfold BIGSHADOW_LO, WAI.WLO; simpl_sizes; slia ]
            | idtac "note: dropping the interceptor environment at a store:" H; clear H ]
  | H : WAI.tush m ?pdq |- _ =>
      first [ apply (WAI.tush_write m pdq a bs) in H;
              [ | unfold WAI.IMGTOP; simpl_sizes; slia | simpl_sizes; slia | unfold BIGSHADOW_LO, WAI.WLO; simpl_sizes; slia ]
            | idtac "note: dropping the TU-buffer shadow facts at a store:" H; clear H ]
  end.

