Ltac after_icpt ST :=
  let ms' := fresh "ms'" in let PO := fresh "PO" in let m1 := fresh "m" in
  let MU1 := fresh "MUi" in let GR1 := fresh "GRi" in let MI1 := fresh "MIi" in let SOK1 := fresh "SOKi" in let WM1 := fresh "WMi" in let ST1 := fresh "ST" in
  cbv beta; intros ms' PO;
  destruct PO as (m1 & ?&?&?&?&?&?&?&?&?&?&?&?&?&? & -> & MU1 & GR1 & MI1 & SOK1);
  rewrite ?unsigned_small64 in MU1 by lia;
  lazymatch type of MU1 with munch _ ?m0 _ =>
    pose proof (WdGrows.wmono_grows Asan_loaded_segments m0 m1 GR1) as WM1;
    pose proof (WdGrows.stk_grows _ m0 m1 _ _ ST GR1) as ST1;
    try match goal with H : mem_inv _ m0 |- _ => clear H end;
    transport_after_call Asan_loaded_segments m0 m1 MU1 WM1;
    clear MU1 WM1 GR1; try clear m0; try rename ST1 into ST; try rename MI1 into MI
  end.

