Ltac senv_sync := repeat match goal with
  | H : WAI.senv ?m ?lo, MU : munch ?W ?m ?m' |- _ =>
      tryif constr_eq m m' then fail else
        (let G := fresh "WL" in pose proof (proj1 H : (WAI.WLO <= lo)%Z) as G; unfold WAI.WLO in G;
         apply (fun E => WAI.senv_munch W m m' lo E MU) in H; [ clear G | wai_wok ])
  end.
Ltac tush_sync := repeat match goal with
  | H : WAI.tush ?m ?pd, MU : munch ?W ?m ?m' |- _ =>
      tryif constr_eq m m' then fail else
        (apply (fun T => WAI.tush_munch W m m' pd T MU) in H; [ | wai_wok ])
  end.

