Lemma upd_bytes_app (cs : list byte) (k : nat) (d1 d2 : list byte) : (k + length d1 + length d2 <= length cs)%nat ->
  upd_bytes (upd_bytes cs k d1) (k + length d1) d2 = upd_bytes cs k (d1 ++ d2).
Proof.
