(* [comment removed for export] *)
Lemma fpad_loop : forall (n : nat) (ra sp gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s7 s9 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (i : Z) (bs : list byte),
  mem_inv rsegs m -> u8arr rsegs m (bv_unsigned s0 + -405) bs -> length bs = 9%nat -> (bv_unsigned s0 < 2 ^ 63)%Z -> (1024 <= bv_unsigned s0)%Z ->
  Z.of_nat n = i -> (1 <= i <= 9)%Z -> digs_from bs i ->
  a1 = Z_to_bv 64 (bv_unsigned s0 + -405 + i) ->
  evt rsegs (fun ms' => exists (bs' : list byte) a1' m',
      digs_from bs' 0 /\ length bs' = 9%nat /\
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 99) (Z_to_bv 64 (bv_unsigned s0 + -405)) a1' a2 a3 a4 a5 a6 a7 s2 s3 (Z_to_bv 64 10)
                    (Z_to_bv 64 (bv_unsigned s0 + -405)) (Z_to_bv 64 48) s7 (Z_to_bv 64 MAGIC10) s9 (Z_to_bv 64 9) s11 t3 t4 t5 t6) F
               (Z_to_bv 64 0x142d2c) fc None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned s0 + -405, bv_unsigned s0 + -396)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ u8arr rsegs m' (bv_unsigned s0 + -405) bs')
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 99) a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 (Z_to_bv 64 10)
             (Z_to_bv 64 (bv_unsigned s0 + -405)) (Z_to_bv 64 48) s7 (Z_to_bv 64 MAGIC10) s9 (Z_to_bv 64 9) s11 t3 t4 t5 t6) F
        (Z_to_bv 64 0x142d08) fc None m (seg_rom rsegs)).
