               (Z_to_bv 64 0x142d2c) fc None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned s0 + -405, bv_unsigned s0 + -396)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ u8arr rsegs m' (bv_unsigned s0 + -405) dg /\ u32arr rsegs m' B ws)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 99) a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 (Z_to_bv 64 10)
             (Z_to_bv 64 (bv_unsigned s0 + -405)) (Z_to_bv 64 48) s7 (Z_to_bv 64 MAGIC10) s9 (Z_to_bv 64 9) s11 t3 t4 t5 t6) F
        (Z_to_bv 64 0x142cbc) fc None m (seg_rom rsegs)).
