Lemma digs_from_app (pre digs : list byte) (nd : nat) : length pre = (9 - nd)%nat -> length digs = nd -> (nd <= 9)%nat -> Forall isdigb digs ->
  digs_from (pre ++ digs) (9 - Z.of_nat nd).
Proof.
