Section EStyle.
Variables (sp gp tp s0 : word) (F : bvmap 5 word) (lo B ia iz fa B0 cap lbf : Z).
Variables (rpos rend wbase wfn bufp bsz mode lockv cookie : word) (J : fjunk).
Hypotheses (LO : (lo + 2296 <= bv_unsigned sp)%Z) (SPS : (bv_unsigned sp <= bv_unsigned s0 - 1056)%Z) (HS0 : (bv_unsigned s0 < 2 ^ 63)%Z) (HLO : (0x6b3d78 <= lo)%Z)
           (GE : fgeo lo (bv_unsigned s0) fa B0 cap).

Definition est (ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5 s11 t3 t4 t5 t6 : word) (fc : bv 32) (m : word -> option byte) (pc p id : Z) : machine_state :=
  MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia)) a0 a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 p) (Z_to_bv 64 14757395258967641293) (Z_to_bv 64 48) s5
          (Z_to_bv 64 10) (Z_to_bv 64 (B + 4 * iz)) (Z_to_bv 64 (bv_unsigned s0 + -405)) (Z_to_bv 64 99) (Z_to_bv 64 (B + 4 * id)) s11 t3 t4 t5 t6) F
     (Z_to_bv 64 pc) fc None m (seg_rom rsegs).

Definition epost (m : word -> option byte) (k p : Z) (ibuf : list byte) (ws : list word) (fc : bv 32) : machine_state -> Prop :=
  fun ms' => exists (digs dbuf' : list byte) (pf idf : Z) ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s5' s11' t3' t4' t5' t6' m',
      Forall isdigb digs /\ Z.of_nat (length digs) = p /\ (-9 <= pf <= 0)%Z /\
      ms' = est ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s5' s11' t3' t4' t5' t6' fc m' 0x142c1c pf idf
      /\ munch [(bv_unsigned sp - 2296, bv_unsigned sp); (B0 + k, B0 + k + p); (fa + 40, fa + 48); (bv_unsigned s0 + -405, bv_unsigned s0 + -396)]%Z m m'
      /\ wmono rsegs m m' /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp) /\ u32arr rsegs m' B ws
      /\ rw_cells rsegs m' (bv_unsigned s0 + -432) [C8 (Z_to_bv 64 fa)] /\ rw_cells rsegs m' (bv_unsigned s0 + -405) [CB 9 dbuf']
      /\ fst_at m' fa B0 cap (k + p) lbf (upd_bytes ibuf (Z.to_nat k) digs) rpos rend wbase wfn bufp bsz mode lockv cookie J.

(* [comment removed for export] *)
Lemma enext_loop : forall (n : nat) (ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5 s11 t3 t4 t5 t6 : word) fc m (k id p : Z) (ibuf dbuf : list byte) (ws : list word),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) -> WAI.senv m lo ->
  u32arr rsegs m B ws -> (0 <= ia < id)%Z -> (id < iz)%Z -> Z.of_nat n = (iz - id)%Z -> (iz <= Z.of_nat (length ws))%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z ->
  (bv_unsigned sp <= B)%Z -> (B + 4 * Z.of_nat (length ws) <= bv_unsigned s0 - 544)%Z ->
  limbs_ok ws id iz -> (0 <= p <= 9 * (iz - id))%Z -> (p < 2 ^ 20)%Z ->
  rw_cells rsegs m (bv_unsigned s0 + -432) [C8 (Z_to_bv 64 fa)] -> rw_cells rsegs m (bv_unsigned s0 + -405) [CB 9 dbuf] ->
  fst_at m fa B0 cap k lbf ibuf rpos rend wbase wfn bufp bsz mode lockv cookie J -> (k + p <= cap)%Z ->
  evt rsegs (epost m k p ibuf ws fc) (est ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5 s11 t3 t4 t5 t6 fc m 0x142ae0 p id).
Proof.
